## Code Example: React Component

```javascript
import React, { useState, useEffect, useCallback } from 'react';
import debounce from 'lodash/debounce';

function UserManagement() {
  const [filters, setFilters] = useState({
    fullName: '',
    email: '',
    phone: '',
    role: 'ALL_ROLES',
    pageNumber: 0,
    pageSize: 20,
    sortBy: 'id',
    sortOrder: 'ASC'
  });

  const [users, setUsers] = useState([]);
  const [totalPages, setTotalPages] = useState(0);
  const [loading, setLoading] = useState(false);

  // Debounced search function
  const performSearch = useCallback(
    debounce(async (newFilters) => {
      setLoading(true);
      try {
        const params = new URLSearchParams();

        if (newFilters.fullName) params.append('fullName', newFilters.fullName);
        if (newFilters.email) params.append('email', newFilters.email);
        if (newFilters.phone) params.append('phone', newFilters.phone);
        if (newFilters.role !== 'ALL_ROLES') params.append('role', newFilters.role);

        params.append('pageNumber', newFilters.pageNumber);
        params.append('pageSize', newFilters.pageSize);
        params.append('sortBy', newFilters.sortBy);
        params.append('sortOrder', newFilters.sortOrder);

        const response = await fetch(`/api/users/search?${params}`);
        const data = await response.json();

        setUsers(data.content);
        setTotalPages(data.totalPages);
      } catch (error) {
        console.error('Search error:', error);
      } finally {
        setLoading(false);
      }
    }, 300),
    []
  );

  // Trigger search when filters change
  useEffect(() => {
    performSearch(filters);
  }, [filters, performSearch]);

  const handleFilterChange = (key, value) => {
    setFilters(prev => ({
      ...prev,
      [key]: value,
      pageNumber: 0 // Reset to first page
    }));
  };

  const handleSort = (field) => {
    const newOrder = filters.sortBy === field && filters.sortOrder === 'ASC' ? 'DESC' : 'ASC';
    setFilters(prev => ({
      ...prev,
      sortBy: field,
      sortOrder: newOrder,
      pageNumber: 0
    }));
  };

  return (
    <div className="user-management">
      <h1>Access Management</h1>

      {/* Search Filters */}
      <div className="filters">
        <input
          type="text"
          placeholder="SEARCH NAME (e.g. John Doe)"
          value={filters.fullName}
          onChange={(e) => handleFilterChange('fullName', e.target.value)}
        />

        <input
          type="text"
          placeholder="SEARCH EMAIL (e.g. john@sky.com)"
          value={filters.email}
          onChange={(e) => handleFilterChange('email', e.target.value)}
        />

        <input
          type="text"
          placeholder="SEARCH PHONE (e.g. +84...)"
          value={filters.phone}
          onChange={(e) => handleFilterChange('phone', e.target.value)}
        />

        <select
          value={filters.role}
          onChange={(e) => handleFilterChange('role', e.target.value)}
        >
          <option value="ALL_ROLES">ALL ROLES</option>
          <option value="ADMIN">ADMIN</option>
          <option value="USER">USER</option>
          <option value="OWNER">OWNER</option>
          <option value="STAFF">STAFF</option>
        </select>
      </div>

      {/* Records Count */}
      <div className="record-count">
        {users.length} ACTIVE RECORDS
      </div>

      {/* Users Table */}
      <table className="users-table">
        <thead>
          <tr>
            <th onClick={() => handleSort('fullName')}>USER PROFILE</th>
            <th>CONTACT DETAILS</th>
            <th onClick={() => handleSort('role')}>DESIGNATION</th>
            <th onClick={() => handleSort('active')}>STATUS</th>
            <th>ACTIONS</th>
          </tr>
        </thead>
        <tbody>
          {users.map(user => (
            <tr key={user.id}>
              <td>
                <div className="user-profile">
                  <div className="user-name">{user.fullName}</div>
                  <div className="user-id">ID: #{user.id}</div>
                </div>
              </td>
              <td>
                <div className="contact-details">
                  <div className="email">{user.email}</div>
                  <div className="phone">{user.phone}</div>
                </div>
              </td>
              <td><span className="badge">{user.role}</span></td>
              <td>
                {user.active ? (
                  <span className="status-active">● ACTIVE</span>
                ) : (
                  <span className="status-suspended">● SUSPENDED</span>
                )}
              </td>
              <td>
                <button className="btn-edit">EDIT</button>
                <button className="btn-delete">DELETE</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Pagination */}
      <div className="pagination">
        <button
          onClick={() => handleFilterChange('pageNumber', filters.pageNumber - 1)}
          disabled={filters.pageNumber === 0}
        >
          Previous
        </button>
        <span>
          Page {filters.pageNumber + 1} of {totalPages}
        </span>
        <button
          onClick={() => handleFilterChange('pageNumber', filters.pageNumber + 1)}
          disabled={filters.pageNumber >= totalPages - 1}
        >
          Next
        </button>
      </div>

      {loading && <div className="loading">Loading...</div>}
    </div>
  );
}

export default UserManagement;
```

