### **Example 4: JavaScript Fetch**
```javascript
async function updateUserProfile(userId, updates) {
  try {
    const response = await fetch(`/api/users/${userId}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        fullName: updates.fullName,      // Optional
        phone: updates.phone,            // Optional
        role: updates.role               // Optional
      })
    });

    if (!response.ok) {
      throw new Error(`Error: ${response.status}`);
    }

    const updatedUser = await response.json();
    console.log('User updated successfully:', updatedUser);
    return updatedUser;
  } catch (error) {
    console.error('Update failed:', error);
  }
}

// Usage
updateUserProfile(1, {
  fullName: 'John Doe',
  phone: '+84987654321',
  role: 'ADMIN'
});
```

### **Example 5: React Hook**
```javascript
import { useState } from 'react';

function UserProfileForm({ userId }) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [formData, setFormData] = useState({
    fullName: '',
    phone: '',
    role: ''
  });

  const handleUpdate = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/users/${userId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error('Update failed');

      const updatedUser = await response.json();
      console.log('Profile updated:', updatedUser);

      // Reset form or update state
      setFormData({ fullName: '', phone: '', role: '' });
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleUpdate}>
      <input
        type="text"
        placeholder="Full Name"
        value={formData.fullName}
        onChange={(e) => setFormData({ ...formData, fullName: e.target.value })}
      />
      <input
        type="tel"
        placeholder="Phone"
        value={formData.phone}
        onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
      />
      <select
        value={formData.role}
        onChange={(e) => setFormData({ ...formData, role: e.target.value })}
      >
        <option value="">Select Role</option>
        <option value="ADMIN">Admin</option>
        <option value="USER">User</option>
        <option value="OWNER">Owner</option>
      </select>

      <button type="submit" disabled={loading}>
        {loading ? 'Updating...' : 'Update Profile'}
      </button>

      {error && <div style={{ color: 'red' }}>{error}</div>}
    </form>
  );
}
```

